INSERT INTO `coffee_farms` (`id`, `farmer_id`, `farmer_name`, `farm_name`, `location`, `province`, `latitude`, `longitude`, `altitude_meters`, `altitude_display`, `land_area_hectares`, `total_trees_count`, `primary_varieties`, `soil_type`, `shade_trees`, `organic_status`, `eudr_compliant`, `weather_data`, `plot_boundary`, `patok_list`, `photo_url`, `established_year`, `notes`, `verification_status`, `verification_stamp`) VALUES ('FARM-PGL-01', 'user-petani-1', 'Asep Supriatna', 'Kebun Blok Pasir Kunci (Lereng Gn. Tilu)', 'Desa Margamukti, Kec. Pangalengan, Kab. Bandung', 'Jawa Barat', -7.1824, 107.5612, 1550, '1.500 - 1.620 mdpl', 2.4, 3200, '["Sigarar Utang","Ateng Super","Kartika"]', 'Andosol Vulkanik', '["Pohon Sengon","Lamtoro","Alpukat"]', 'Organik Bersertifikat (SNI / USDA)', 1, '{"currentCondition":"Berkabut Tebal","temperatureCelsius":19.5,"humidityPercent":78,"annualRainfallMm":2200,"sunshineHoursPerDay":6.5,"windSpeedKph":11,"microclimateNote":"Suhu malam dingin (14°C) dengan kabut pagi tebal memperlambat pematangan ceri, menghasilkan akumulasi gula brix tinggi dan densitas biji optimal."}', NULL, '[{"id":"PTK-01","name":"Patok 1 (Sudut Utara - Batas Hutan Lindung)","latitude":-7.1816,"longitude":107.5608,"elevationMeters":1575,"physicalType":"Patok Beton BPN","condition":"Kondisi Baik & Kokoh","landmarkNote":"Sebelah pohon beringin tua, 15m dari aliran mata air Cikunci","verifiedDate":"2026-08-15"},{"id":"PTK-02","name":"Patok 2 (Sudut Timur Laut - Jalan Tani)","latitude":-7.1819,"longitude":107.5621,"elevationMeters":1560,"physicalType":"Patok Beton BPN","condition":"Kondisi Baik & Kokoh","landmarkNote":"Di persimpangan jalan setapak blok timur","verifiedDate":"2026-08-15"},{"id":"PTK-03","name":"Patok 3 (Sudut Tenggara - Batas Kebun Teh)","latitude":-7.1831,"longitude":107.5619,"elevationMeters":1540,"physicalType":"Pipa Besi Cor","condition":"Kondisi Baik & Kokoh","landmarkNote":"Batas parit terasering kebun teh Malabar","verifiedDate":"2026-08-15"},{"