ut air."},{"dayNumber":8,"date":"2026-09-19","moisturePercent":16.2,"ambientTempCelsius":28.9,"rhPercent":60,"turningFrequency":"Tiap 3 Jam","notes":"Ceri mengering merata."},{"dayNumber":11,"date":"2026-09-22","moisturePercent":12.8,"ambientTempCelsius":29.8,"rhPercent":52,"turningFrequency":"Tiap 2 Jam","notes":"Kadar air mencapai 12.8%. Perlu 1 hari jemur lagi untuk mencapai target <= 12.0%."}],"operatorName":"Ahmad Penjemuran","notes":"Penjemuran di solar dome terlindung hujan. Lanjutkan penjemuran hingga kadar air stabil di 11.2%."}', '{"siloBinId":"BIN-GABAH-01","packagingType":"GrainPro Hermetic 50kg","startDate":"2026-09-23","targetRestingDays":45,"completedDays":0,"ambientTempCelsius":20.5,"ambientRhPercent":54,"moistureStabilizedPercent":11.2,"waterActivityAw":0.57,"operatorName":"Hendra Warehouse QA","notes":"Menunggu target kadar air penjemuran selesai untuk proses resting."}', '{"millingDate":"2026-10-15","machineId":"Pinhalense DH-500 Dry Huller","inputParchmentWeightKg":280,"outputGreenBeanWeightKg":145,"outputHuskWeightKg":130,"outputDustWeightKg":5,"millingEfficiencyPercent":51.8,"operatorName":"Sulaeman Miller","notes":"Estimasi output hulling berdasarkan rendemen biji kering."}', NULL, NULL, NULL, NULL, NULL, NULL, '{"wasteType":"Kulit Ceri (Pulp / Cascara)","utilization":"Bahan Baku Minuman Teh Cascara & Kompos Sirkular","weightKgOrLiters":380,"recipientOrLocation":"Unit Artisan Cascara Malabar & Kebun Tilu Organik","processingMethod":"Pengeringan Solar Raised Bed (Food Grade) & Kompos Aerobik 30 Hari","ecoCertificate":"sangrAI Zero-Waste Circular Verified","notes":"Kulit ceri disortasi higienis untuk minuman teh cascara specialty, lendir organik dikomposkan.","ecoRating":4.92,"ecoScore":98,"diversionRatePercent":98.2,"carbonOffsetKg":171}', 'in_progress');
